const NL = String.fromCharCode(10);
const FENCE = String.fromCharCode(96, 96, 96);
const raw = $input.first().json;
const blocks = Array.isArray(raw.content) ? raw.content : [];

// Text Claude wrote (search calls and results are separate blocks).
const textBlocks = blocks.filter(b => b && b.type === 'text' && typeof b.text === 'string').map(b => b.text);
const fallbackText = [raw.merged_response, raw.text, raw.output].find(t => typeof t === 'string');
if (!textBlocks.length && !fallbackText) throw new Error('No text in Claude response: ' + JSON.stringify(raw).slice(0, 300));

// Real article links: web search results plus citations on text blocks.
const sources = [];
for (const b of blocks) {
  if (b && b.type === 'web_search_tool_result' && Array.isArray(b.content)) {
    for (const r of b.content) if (r && r.url) sources.push({ url: r.url, title: r.title || '' });
  }
  if (b && Array.isArray(b.citations)) {
    for (const c of b.citations) if (c && c.url) sources.push({ url: c.url, title: c.title || '', text: c.cited_text || '' });
  }
}

function parseArray(text) {
  const s = String(text).split(FENCE + 'json').join('').split(FENCE).join('').trim();
  const end = s.lastIndexOf(']');
  for (let i = s.indexOf('['); i >= 0 && i < end; i = s.indexOf('[', i + 1)) {
    try {
      const v = JSON.parse(s.slice(i, end + 1));
      if (Array.isArray(v)) return v;
    } catch (e) {}
  }
  return null;
}

// Prefer the last text block (the final answer), then everything joined.
const candidates = [textBlocks[textBlocks.length - 1], textBlocks.join(NL), fallbackText].filter(Boolean);
let data = null;
for (const c of candidates) { data = parseArray(c); if (data) break; }
if (!data) throw new Error('No JSON array found in Claude reply: ' + String(candidates[0]).slice(0, 300));

// Article = a URL with a real path, not just a homepage. (No URL() in the n8n sandbox.)
function isArticle(u) {
  if (typeof u !== 'string' || !/^https?:\/\//i.test(u)) return false;
  const path = u.replace(/^https?:\/\/[^\/]+/i, '').split(/[?#]/)[0].replace(/\/+$/, '');
  return path.length > 8;
}
function findSource(company) {
  const name = String(company).replace(/\(.*?\)/g, '').trim().toLowerCase();
  if (!name) return null;
  const slug = name.replace(/[^a-z0-9]+/g, '-');
  const hit = sources.find(s => isArticle(s.url) && (
    s.title.toLowerCase().includes(name) || s.url.toLowerCase().includes(slug) || String(s.text || '').toLowerCase().includes(name)));
  return hit ? hit.url : null;
}

const covered = new Set($('Get Covered Companies').all().map(i => String(i.json.company || '').toLowerCase().trim()).filter(Boolean));
const seen = new Set();
const rounds = [];
for (const r of data) {
  if (!r || !r.company || !r.amount) continue;
  if (['null', 'undefined', 'n/a', 'na', 'undisclosed', 'unknown', 'none'].includes(String(r.amount).trim().toLowerCase())) continue;
  const key = String(r.company).toLowerCase().trim();
  if (covered.has(key) || seen.has(key)) continue;
  seen.add(key);
  if (!r.url || !isArticle(r.url)) r.url = findSource(r.company);
  r.company = String(r.company).trim();
  r.amount = String(r.amount).trim();
  r.round = r.round ? String(r.round) : '';
  r.city = r.city ? String(r.city) : '';
  r.country = r.country ? String(r.country) : '';
  r.investors = Array.isArray(r.investors) ? r.investors : [];
  r.check = r.check === true;
  rounds.push(r);
}
return [{ json: { count: rounds.length, rounds: rounds, sources_found: sources.length, rounds_text: rounds.map((r, i) => i + ': ' + JSON.stringify(r)).join(NL) } }];

