const NL = String.fromCharCode(10);
const FENCE = String.fromCharCode(96, 96, 96);
function extractText(j) {
  if (Array.isArray(j.content)) {
    return j.content.filter(function (b) { return b && b.type === 'text'; }).map(function (b) { return b.text; }).join(NL);
  }
  if (typeof j.merged_response === 'string') return j.merged_response;
  if (typeof j.text === 'string') return j.text;
  if (typeof j.output === 'string') return j.output;
  throw new Error('No text blocks in Claude response: ' + JSON.stringify(j).slice(0, 300));
}
function parseJson(text, kind) {
  const s = String(text).split(FENCE + 'json').join('').split(FENCE + 'JSON').join('').split(FENCE).join('').trim();
  const open = kind === 'array' ? '[' : '{';
  const close = kind === 'array' ? ']' : '}';
  const start = s.indexOf(open);
  const end = s.lastIndexOf(close);
  if (start < 0 || end < start) throw new Error('No JSON ' + kind + ' found in Claude reply: ' + s.slice(0, 300));
  try {
    return JSON.parse(s.slice(start, end + 1));
  } catch (e) {
    throw new Error('Invalid JSON from Claude: ' + e.message + ' | ' + s.slice(0, 300));
  }
}

const rounds = $('Parse Research').first().json.rounds || [];
let out = {};
try { out = parseJson(extractText($input.first().json), 'object') || {}; } catch (e) { out = {}; }
const picks = Array.isArray(out.picks) ? out.picks : [];
const used = new Set();
const items = [];
for (const p of picks) {
  const idx = Number(p.i);
  if (!rounds[idx] || used.has(idx)) continue;
  used.add(idx);
  const r = rounds[idx];
  items.push({ json: Object.assign({}, r, { why: p.why || '', trend: out.trend || '', round_json: JSON.stringify(r) }) });
  if (items.length === 3) break;
}
if (!items.length) {
  // Fallback: Pick step failed or returned nothing usable, take the first rounds so the run still produces posts.
  rounds.slice(0, 3).forEach(function (r) {
    items.push({ json: Object.assign({}, r, { why: '', trend: '', round_json: JSON.stringify(r) }) });
  });
}
if (!items.length) throw new Error('Pick step returned no valid picks: ' + JSON.stringify(out).slice(0, 300));
return items;

const FENCE = String.fromCharCode(96, 96, 96);
const r = $('Loop Over Picks').first().json;
const raw = $input.first().json;
const blocks = Array.isArray(raw.content) ? raw.content : [];

// The JSON answer is in the last text block; search calls and thinking are separate blocks.
const textBlocks = blocks.filter(b => b && b.type === 'text' && typeof b.text === 'string').map(b => b.text);
const fallbackText = [raw.merged_response, raw.text, raw.output].find(t => typeof t === 'string');
const candidates = [textBlocks[textBlocks.length - 1], textBlocks.join(' '), fallbackText].filter(Boolean);

function parseObject(text) {
  const s = String(text).split(FENCE + 'json').join('').split(FENCE).join('').trim();
  const end = s.lastIndexOf('}');
  for (let i = s.indexOf('{'); i >= 0 && i < end; i = s.indexOf('{', i + 1)) {
    try {
      const v = JSON.parse(s.slice(i, end + 1));
      if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    } catch (e) {}
  }
  return null;
}
let o = null;
for (const c of candidates) { o = parseObject(c); if (o) break; }
if (!o) throw new Error('Write step for ' + r.company + ': no JSON object in reply: ' + String(candidates[0] || '').slice(0, 300));
if (!o.headline || !o.post) throw new Error('Write step for ' + r.company + ': missing headline or post');

// Links Claude actually saw in this step's web search.
const sources = [];
for (const b of blocks) {
  if (b && b.type === 'web_search_tool_result' && Array.isArray(b.content)) {
    for (const s of b.content) if (s && s.url) sources.push({ url: s.url, title: s.title || '' });
  }
  if (b && Array.isArray(b.citations)) {
    for (const c of b.citations) if (c && c.url) sources.push({ url: c.url, title: c.title || '' });
  }
}

// Article = a URL with a real path, not just a homepage. (No URL() in the n8n sandbox.)
function isArticle(u) {
  if (typeof u !== 'string' || !/^https?:\/\//i.test(u)) return false;
  const path = u.replace(/^https?:\/\/[^\/]+/i, '').split(/[?#]/)[0].replace(/\/+$/, '');
  return path.length > 8;
}
const norm = u => String(u || '').replace(/^https?:\/\/(www\.)?/i, '').replace(/\/+$/, '').toLowerCase();
const seenUrls = new Set(sources.map(s => norm(s.url)));
const name = String(r.company).replace(/\(.*?\)/g, '').trim().toLowerCase();
const slug = name.replace(/[^a-z0-9]+/g, '-');

// 1) Claude's pick, only if it appeared in the search results. 2) A result that names the company. 3) Research URL.
let url = null;
if (isArticle(o.source_url) && seenUrls.has(norm(o.source_url))) url = o.source_url;
if (!url) {
  const hit = sources.find(s => isArticle(s.url) && (s.title.toLowerCase().includes(name) || s.url.toLowerCase().includes(slug)));
  if (hit) url = hit.url;
}
if (!url && isArticle(r.url)) url = r.url;

const rawTags = Array.isArray(o.hashtags) ? o.hashtags : String(o.hashtags || '').split(' ');
const tags = rawTags.map(t => String(t).trim()).filter(Boolean).map(t => (t.charAt(0) === '#' ? t : '#' + t));

// Cost of this Write call at list price (Haiku 5.5: $0.10 / $0.50 per M tokens, web search $0.01 each).
const u = raw.usage || {};
const searches = (u.server_tool_use && u.server_tool_use.web_search_requests) || 0;
const cost = ((u.input_tokens || 0) + (u.cache_creation_input_tokens || 0)) * 0.10e-6
  + (u.cache_read_input_tokens || 0) * 0.01e-6 + (u.output_tokens || 0) * 0.50e-6 + searches * 0.01;

return [{ json: {
  company: r.company,
  city: r.city || '',
  country: r.country || '',
  amount: r.amount,
  round: r.round || '',
  url: url || '',
  check: r.check === true || o.amount_mismatch === true,
  headline: String(o.headline).trim(),
  post: String(o.post).trim(),
  post_x: String(o.post_x || '').trim().slice(0, 240),
  hashtags: tags.join(' '),
  cost_usd: Math.round(cost * 1e5) / 1e5
} }];
